1	import React, { useEffect, useState } from 'react';
2	import { Modal, ModalOverlay, ModalContent, useMultiStyleConfig } from '@chakra-ui/react';
3	
4	const ZIMM_MODAL_RECIPE = 'ZimmModal';
5	
6	type ZimmModalProps = {
7	  /** Whether the dialog is open. Nothing renders until this and `mounted` are both true. */
8	  isOpen: boolean;
9	  /** From the paired useZimmModal() call — false until the first client render, so the portal
10	   *  is never created during SSR. */
11	  mounted: boolean;
12	  /** Called on backdrop click and on Escape (both handled by Chakra's Modal). */
13	  onClose: () => void;
14	  /** Dialog panel max-width. No default — each modal type has its own Figma-specified size, so
15	   *  a caller-supplied value is safer than a guessed generic default. */
16	  maxWidth: string;
17	  /** id of the element that labels the dialog (aria-labelledby). */
18	  labelledBy: string;
19	  /** id of the element that describes the dialog (aria-describedby), if one exists. */
20	  describedBy?: string;
21	  children: React.ReactNode;
22	};
23	
24	/**
25	 * Generic modal chrome — portal, backdrop, and an accessible dialog panel, built on Chakra's
26	 * Modal primitive (focus trap, initial focus, focus restore, body-scroll lock, and Escape/
27	 * overlay-click-to-close all come from Chakra rather than being hand-rolled). Owns none of the
28	 * content: a caller supplies its own form/fields as children. Public props are unchanged from
29	 * the previous hand-rolled implementation, so existing consumers (ZimmSubscribeModal) require
30	 * no changes.
31	 *
32	 * @param props see ZimmModalProps
33	 */
34	export const ZimmModal = ({
35	  isOpen,
36	  mounted,
37	  onClose,
38	  maxWidth,
39	  labelledBy,
40	  describedBy,
41	  children,
42	}: ZimmModalProps) => {
43	  const styles = useMultiStyleConfig(ZIMM_MODAL_RECIPE, {});
44	  // A React-state-backed ref, not a plain `useRef` — see the effect below for why.
45	  const [contentNode, setContentNode] = useState<HTMLElement | null>(null);
46	
47	  /*
48	   * `aria-labelledby`/`aria-describedby` as plain props on `<ModalContent>` are silently
49	   * dropped — confirmed by reading @chakra-ui/modal's source (`chunk-XG6IELTC.mjs`'s
50	   * `getDialogProps`), not assumed. It unconditionally recomputes both from its own
51	   * `ModalHeader`/`ModalBody`-mount tracking (`headerMounted ? headerId : undefined`, same for
52	   * `bodyMounted`/`bodyId`) *after* spreading whatever props we pass, so ours are always
53	   * overwritten. Since ZimmModal's children are opaque — callers render their own title/body,
54	   * never Chakra's `ModalHeader`/`ModalBody` — those always compute to `undefined`, silently
55	   * dropping the ids this component exists to carry. This is a real Chakra 2.7 constraint, not
56	   * a `__css`-vs-`sx` prop-mechanism issue (that fix, applied elsewhere in ZimmDrawer, doesn't
57	   * apply here — `aria-labelledby` isn't a style prop). Setting the attributes directly on the
58	   * rendered DOM node is the only way to make them stick without restructuring every consumer's
59	   * children into Chakra's `ModalHeader`/`ModalBody` slots, which would be a much larger, breaking
60	   * change to this component's public API.
61	   *
62	   * A plain `useRef` + `useEffect(() => {...}, [isOpen, ...])` looked right but doesn't work:
63	   * confirmed by inspection that `ModalContent`'s dialog `<section>` mounts via Chakra's own
64	   * Portal, which does its own two-pass mount (an internal effect flips a "has portal target"
65	   * flag before the real DOM node exists) — so on `isOpen`'s *first* transition to `true`, our
66	   * effect fires and reads the ref before Chakra's Portal has actually attached it, and never
67	   * fires again since none of `[isOpen, labelledBy, describedBy]` change on Portal's own later
68	   * commit. A callback ref (via `useState`, not a mutable `useRef`) sidesteps this entirely: it
69	   * fires exactly when React actually attaches/detaches the real node, whichever commit that is,
70	   * and storing it in state makes the effect below re-run at that point too.
71	   */
72	  useEffect(() => {
73	    if (!isOpen || !contentNode) return;
74	    contentNode.setAttribute('aria-labelledby', labelledBy);
75	    if (describedBy) {
76	      contentNode.setAttribute('aria-describedby', describedBy);
77	    } else {
78	      contentNode.removeAttribute('aria-describedby');
79	    }
80	  }, [isOpen, contentNode, labelledBy, describedBy]);
81	
82	  if (!mounted) return null;
83	
84	  return (
85	    <Modal isOpen={isOpen} onClose={onClose} isCentered>
86	      <ModalOverlay __css={{ background: styles.overlay.background, zIndex: styles.overlay.zIndex }} />
87	      <ModalContent ref={setContentNode} __css={{ ...styles.panel, maxWidth, margin: styles.overlay.padding }}>
88	        {children}
89	      </ModalContent>
90	    </Modal>
91	  );
92	};
93

1	import React, { useId, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
4	import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';
5	import { ZimmTabs } from 'app/components/ui-kits/molecules/zimmTabs';
6	import type { ZimmTabItem } from 'app/components/ui-kits/molecules/zimmTabs';
7	
8	const ZIMM_PDP_DRAWER_RECIPE = 'ZimmPdpDrawer';
9	
10	export type ZimmPdpDrawerTab = ZimmTabItem & {
11	  content: React.ReactNode;
12	};
13	
14	type ZimmPdpDrawerProps = {
15	  isOpen: boolean;
16	  onClose: () => void;
17	  size: ZimmDrawerSize;
18	  /** SFCC-266's EU Environmental Qualities tab, SFCC-102's Size Guide, etc. all pass their own
19	   *  content component here — this organism owns none of it (SFCC-736's scope is shell only). */
20	  tabs: ZimmPdpDrawerTab[];
21	  /** Which tab is active when the drawer mounts — e.g. the tab the triggering info-link maps to.
22	   *  Only read on first mount; pass a `key` at the call site to force a reset on reopen with a
23	   *  different starting tab. */
24	  initialTabId?: string;
25	  /** No visible title exists in the tabbed header (unlike a plain-title drawer), so this is
26	   *  required rather than filled with placeholder copy. */
27	  ariaLabel: string;
28	};
29	
30	/**
31	 * The SFCC-736 pdp/drawer deliverable — composes ZimmDrawer (shell) with ZimmTabs (nav header)
32	 * and swaps content by active tab. Renders the shell even with an empty `tabs` array (AC 11).
33	 *
34	 * @param props see ZimmPdpDrawerProps
35	 */
36	export const ZimmPdpDrawer = ({ isOpen, onClose, size, tabs, initialTabId, ariaLabel }: ZimmPdpDrawerProps) => {
37	  const styles = useMultiStyleConfig(ZIMM_PDP_DRAWER_RECIPE, { variant: size });
38	  // `initialTabId` only wins when it actually matches one of `tabs` — an id from a stale caller
39	  // or a typo would otherwise select no tab at all, and ZimmTabs gives every tab `tabIndex={-1}`
40	  // when none is active, so keyboard users could never enter the tablist.
41	  const initialTab = tabs.find((tab) => tab.id === initialTabId);
42	  const [activeTabId, setActiveTabId] = useState(initialTab?.id ?? tabs[0]?.id ?? '');
43	  // Shared with ZimmTabs (as `idPrefix`) so each tab's `id`/`aria-controls` and this panel's
44	  // `id`/`aria-labelledby` reference each other correctly — `useId()` keeps it unique even with
45	  // more than one tabbed drawer mounted at once (this page also mounts an untabbed ZimmDrawer).
46	  const idPrefix = useId();
47	
48	  const activeTab = tabs.find((tab) => tab.id === activeTabId);
49	
50	  return (
51	    <ZimmDrawer isOpen={isOpen} onClose={onClose} size={size} aria-label={ariaLabel}>
52	      {tabs.length > 0 && (
53	        <ZimmTabs
54	          tabs={tabs}
55	          activeTabId={activeTabId}
56	          onTabChange={setActiveTabId}
57	          size={size}
58	          ariaLabel={ariaLabel}
59	          idPrefix={idPrefix}
60	        />
61	      )}
62	      {activeTab ? (
63	        <chakra.div
64	          id={`${idPrefix}-panel`}
65	          role="tabpanel"
66	          aria-labelledby={`${idPrefix}-tab-${activeTabId}`}
67	          tabIndex={0}
68	          __css={styles.content}
69	        >
70	          {activeTab.content}
71	        </chakra.div>
72	      ) : (
73	        // AC 11 — zero tabs (or an activeTabId with no matching tab) still renders the shell,
74	        // but with no tab to relate a panel to, `role="tabpanel"`/`aria-labelledby` would
75	        // reference a nonexistent tab id — a plain container carries no such claim.
76	        <chakra.div __css={styles.content} />
77	      )}
78	    </ZimmDrawer>
79	  );
80	};
