8	
9	export type ZimmWishlistAuthDrawerProps = {
10	  /**
11	   * Called after successful passwordless/OTP login. Not invoked for IDP (Apple/Google)
12	   * flows — those trigger a full browser redirect; the user lands back already logged in.
13	   */
14	  onAuthSuccess?: () => void;
15	  /** Identifies this mounted instance so a social-IDP round-trip resumes the right
16	   *  `onAuthSuccess` — required because more than one instance (e.g. header + PDP) can be
17	   *  mounted on the page the shopper returns to. Stable per call site, e.g. `'header-wishlist'`
18	   *  or `'pdp-wishlist'` — see `useWishlistAuthDrawer`'s own doc comment. */
19	  intentId: string;
20	  /** The single trigger element (button, icon-button, etc.). Its onClick is replaced by the
21	   *  auth-gate handler — call the original action via onAuthSuccess instead. */
22	  children: React.ReactElement;
23	};
24	
25	/**
26	 * Organism — wraps a single trigger element and gates its action behind auth.
27	 * If the customer is already registered the original onClick fires immediately.
28	 * If not, the Zimmermann auth drawer opens instead (passwordless email + optional social IDPs).
29	 *
30	 * Drop-in replacement for `withRegistration(Button)` on wishlist-specific entry points.
31	 * All SDK and auth logic lives in `useWishlistAuthDrawer` — this component is purely presentational.
32	 */
33	export const ZimmWishlistAuthDrawer = ({ onAuthSuccess, intentId, children }: ZimmWishlistAuthDrawerProps) => {
34	  const {
35	    isOpen,
36	    handleDrawerClose,
37	    handleTriggerClick,
38	    triggerRef,
39	    drawerTitle,
40	    description,
41	    emailValue,
42	    onEmailChange,
43	    onSendCode,
44	    onSignInWithApple,
45	    onSignInWithGoogle,
46	    isSocialEnabled,
47	    isPasswordlessEnabled,
48	    emailInputRef,
49	    onCreateAccount,
50	    isOtpAuthOpen,
51	    onOtpAuthClose,
52	    form,
53	    handlePasswordlessLogin,
54	    handleOtpVerification,
55	    registerModal,
56	  } = useWishlistAuthDrawer({ onAuthSuccess, intentId });
57	
58	  return (
59	    <>
60	      {React.cloneElement(React.Children.only(children), { onClick: handleTriggerClick })}
61	      <ZimmDrawer
62	        isOpen={isOpen}
63	        onClose={handleDrawerClose}
64	        size="small"
65	        title={drawerTitle}
66	        finalFocusRef={triggerRef}
67	        initialFocusRef={emailInputRef}
68	      >
69	        <ErrorFallback>
70	          <ZimmAuthDrawerContent
71	            description={description}
72	            emailValue={emailValue}
73	            onEmailChange={onEmailChange}
74	            onSendCode={onSendCode}
75	            onSignInWithApple={onSignInWithApple}
76	            onSignInWithGoogle={onSignInWithGoogle}
77	            onCreateAccount={onCreateAccount}
78	            socialEnabled={isSocialEnabled}
79	            passwordlessEnabled={isPasswordlessEnabled}
80	            initialFocusRef={emailInputRef}
81	          />
82	        </ErrorFallback>
83	      </ZimmDrawer>
84	      <AuthModal {...registerModal} />
85	      <OtpAuth
86	        isOpen={isOtpAuthOpen}
87	        onClose={onOtpAuthClose}
88	        form={form}
89	        handleSendEmailOtp={handlePasswordlessLogin}
90	        handleOtpVerification={handleOtpVerification}
91	        hideCheckoutAsGuestButton={true}
92	      />
93	    </>
94	  );
95	};
