// jsdom has no IntersectionObserver or Element.scrollIntoView.
let latestObserverCallback: IntersectionObserverCallback | null = null;
class MockIntersectionObserver {
  constructor(callback: IntersectionObserverCallback) {
    latestObserverCallback = callback;
  }
  observe = vi.fn();
  disconnect = vi.fn();
  unobserve = vi.fn();
}

let scrollIntoViewMock: ReturnType<typeof vi.fn>;

beforeEach(() => {
  latestObserverCallback = null;
  // @ts-expect-error - jsdom has no native IntersectionObserver
