import { useEffect, useRef, useState } from 'react';

type UseZimmModalParams = {
  /** Whether the dialog is currently open. */
  isOpen: boolean;
  /** Called when the dialog should close. Unused now that Chakra's Modal owns Escape/overlay-
   *  click handling directly, but kept in the param type so existing call sites need no change. */
  onClose: () => void;
};

type UseZimmModalReturn = {
  /** False until after the first client render, so the dialog is not rendered during SSR. */
  mounted: boolean;
  /** Attach to the element that bounds the dialog's own content — kept for existing markup
   *  compatibility. Chakra's Modal now traps focus across the whole ModalContent itself, so this
   *  ref is no longer load-bearing. */
  trapRef: React.RefObject<HTMLElement>;
  /** Attach to the wrapper around the first field — kept for existing markup compatibility.
   *  Chakra's Modal now auto-focuses the first focusable element on open by default. */
  firstFocusRef: React.RefObject<HTMLDivElement>;
};

/**
 * Mount gating for the dialog. Focus trap, initial focus, focus restore, body-scroll lock, and
 * Escape/overlay-click-to-close all moved onto Chakra's Modal primitive when ZimmModal was
 * rebuilt on it — this hook now only tracks first-client-render so ZimmModal doesn't render
 * before hydration. Still returns trapRef/firstFocusRef so ZimmSubscribeModal's existing markup
 * needs no changes; neither ref drives behaviour any more.
 *
 * @param params isOpen and the close callback — unused by this hook now (see UseZimmModalParams),
 *   kept only so the call-site's object literal still type-checks against the same shape.
 * @returns the mount flag plus the two (now inert) refs the dialog markup still attaches
 */
// eslint-disable-next-line @typescript-eslint/no-unused-vars -- signature kept for call-site compatibility, see JSDoc above
export const useZimmModal = (_params: UseZimmModalParams): UseZimmModalReturn => {
  const [mounted, setMounted] = useState(false);
  const trapRef = useRef<HTMLElement>(null);
  const firstFocusRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setMounted(true);
  }, []);

  return { mounted, trapRef, firstFocusRef };
};

